ROWS=[json.loads(x) for x in (ROOT/'data/raw_candidates/wawards_azerbaijan.jsonl').read_text(encoding='utf-8').splitlines() if x.strip()];OUT=ROOT/'assets/images/azerbaijan_wawards_families';OUT.mkdir(parents=True,exist_ok=True);records=[];images=[]
for row in ROWS:
 slug=Path(urlparse(row['object_url']).path).stem;family=f"AZE-WA-{slug.upper().replace('-', '_')}";item=row['original_images'][0];src=ROOT/item['local_path'];rel=f"assets/images/azerbaijan_wawards_families/{slug}{src.suffix.lower()}";shutil.copy2(src,ROOT/rel)
 with Image.open(src) as im:w,h=im.size;im.verify()
 rid=family+'-REPRESENTATIVE';view=rid+'-VIEW1';date=(row.get('date_candidates') or ['日期待考'])[0]
 if date!='日期待考':date=f'{date}年设立／纪年'
 records.append({'id':rid,'family':family,'country_zh':'阿塞拜疆共和国','name':NAMES[slug],'original':row['page_title'],'date':date,'variant':'World Awards对象页所示完整章体；具体等级待考','views':[{'key':view,'label':'完整图样'}],'source_ids':[row['source_id']],'image_kind':'catalogue_object_or_illustration','html_eligible':True})
 images.append({'key':rid.lower()+'-image','record_id':rid,'view_key':view,'local_path':rel,'source_page':row['object_url'],'image_url':item['image_url'],'license':'source-site research use; publication rights not asserted','dimensions':[w,h],'bytes':src.stat().st_size,'sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'decoded':True,'visually_checked':True})
(ROOT/'data/volumes/azerbaijan_wawards_families.json').write_text(json.dumps({'as_of':'2026-09-28','volume':'阿塞拜疆共和国','records':records},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'data/volumes/azerbaijan_wawards_families_manifest.json').write_text(json.dumps({'as_of':'2026-09-28','images':images,'unpictured_candidates':[],'notes':['Known duplicate legacy rows are excluded by site_build; unique liberation and honorary-title variants remain retained.']},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'source_rows':len(ROWS),'formal_rows':len(records),'families':len({r['family'] for r in records}),'views':len(images)},ensure_ascii=False))
